// 经典面试题：执行顺序
console.log('1');

setTimeout(() => {
  console.log('2');
  Promise.resolve().then(() => console.log('3'));
}, 0);

Promise.resolve().then(() => {
  console.log('4');
  setTimeout(() => console.log('5'), 0);
});

console.log('6');

// 输出：1 6 4 2 3 5
// 解释：
// 1. 同步代码：1, 6
// 2. 微任务：4
// 3. 宏任务setTimeout：2
// 4. 微任务：3
// 5. 宏任务setTimeout：5

// Node.js中process.nextTick优先级
console.log('start');

setTimeout(() => console.log('timeout'), 0);

Promise.resolve().then(() => console.log('promise'));

process.nextTick(() => console.log('nextTick'));

console.log('end');

// Node输出：start end nextTick promise timeout
// nextTick在所有微任务之前执行

// async/await的执行顺序
async function async1() {
  console.log('async1 start');
  await async2();
  console.log('async1 end'); // 相当于Promise.then
}
async function async2() {
  console.log('async2');
}
console.log('script start');
setTimeout(() => console.log('timeout'), 0);
async1();
new Promise(resolve => {
  console.log('promise1');
  resolve();
}).then(() => console.log('promise2'));
console.log('script end');

// 输出：script start → async1 start → async2 → promise1
//       → script end → async1 end → promise2 → timeout
